# Let's manually implement the approach step by step

inputs = ['kh', 'bu', 'wzd', 'fzk', 'fjceg']
outputs = ['kjfw', 'ayu', 'kaydzd', 'fzk', 'fjceg']

# Step 1: Find changed pairs
def find_changed_pairs(inputs, outputs):
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:", changed)

# Step 2: For each changed pair, find minimal edit
def find_minimal_edit(s_in, s_out):
    # Simple approach: find first differing position and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if we're inserting or replacing
            if len(s_in) == len(s_out):
                # Replace
                return (s_in[i], s_out[i], i)
            elif len(s_in) < len(s_out):
                # Insert
                return ("", s_out[i], i)
            else:
                # Delete  
                return (s_in[i], "", i)

    # If we get here, one string is prefix of the other
    if len(s_in) < len(s_out):
        # Insert at end
        return ("", s_out[len(s_in)], len(s_in))
    elif len(s_in) > len(s_out):
        # Delete at end
        return (s_in[len(s_out)], "", len(s_out))
    else:
        return ("", "", -1)  # No change

print("\nAnalyzing each changed pair:")
for idx, s_in, s_out in changed:
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    print(f"  {s_in} -> {s_out}: replace '{old_sub}' with '{new_sub}' at position {pos}")

